package com.day18.auth.model; import jakarta.persistence.*; @Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(unique=true,nullable=false) public String username; @Column(nullable=false) public String passwordHash; @Column(nullable=false) public String role="USER"; public User(){} public User(String u,String p){username=u;passwordHash=p;} }
